mapper.sql:
from cms_fail_code f left join mst_equip_class c on c.class_id = f.equip_class_id

  f.code_type = #{codeType}
  and f.use_yn = #{useYn}
  and (f.fail_cd like #{keyword} escape '\' or f.fail_nm ilike #{keyword} escape '\')

mapper.select:
select 
  from cms_fail_code f left join mst_equip_class c on c.class_id = f.equip_class_id
 where f.fail_id = #{id}

select 
  from cms_fail_code f left join mst_equip_class c on c.class_id = f.equip_class_id
 where f.code_type = #{codeType} and f.fail_cd = #{failCd}

mapper.update:
update cms_fail_code
   set fail_nm = #{f.failNm}, fail_cat = #{f.failCat}, equip_class_id = #{f.equipClassId}, sort_no = #{f.sortNo},
       use_yn = #{f.useYn}, remark = #{f.remark}, row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where fail_id = #{id} and row_ver = #{f.rowVer}

mapper.sql:
where e.use_yn = 'Y'
  and e.plant_cd = #{plantCd}
  and (e.equip_cd like #{keyword} escape '\' or e.equip_nm ilike #{keyword} escape '\')
  and coalesce(p.criticality, 'C') = #{criticality}
  and p.key_equip_yn = 'Y'

mapper.select:
select  

 order by e.plant_cd, e.equip_cd
 limit #{limit}

mapper.update:
update cms_equip_profile
   set criticality = #{criticality}, key_equip_yn = #{keyEquipYn}, owner_user_id = #{ownerUserId}, ideal_ct_sec = #{idealCtSec},
       remark = #{remark},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where equip_id = #{equipId} and row_ver = #{rowVer}

mapper.select:
select * from (
     where e.use_yn = 'Y'
      and (e.equip_cd like #{keyword} escape '\' or e.equip_nm ilike #{keyword} escape '\')
      and e.plant_cd = #{plantCd}

    union all
     where a.use_yn = 'Y' and a.asset_type in ('MOLD', 'JIG')
      and (a.asset_cd like #{keyword} escape '\' or a.asset_nm ilike #{keyword} escape '\')

) t order by t.target_type desc, t.code limit #{limit}

mapper.sql:
where m.reported_at >= #{c.from} and m.reported_at < #{c.to}
  and m.status in #{s}
  and m.mwo_type = #{c.mwoType}
  and m.plant_cd = #{c.plantCd}
  and m.equip_id = #{c.equipId}
  and m.assignee_id = #{c.assigneeId}
  and m.requested_by = #{c.requestedBy}
  and m.report_req_id is not null
  and (m.mwo_no like #{c.keyword} escape '\' or m.title ilike #{c.keyword} escape '\'
       or e.equip_cd like #{c.keyword} escape '\' or a.asset_cd like #{c.keyword} escape '\')

mapper.select:
select  

 order by m.reported_at desc, m.mwo_id desc
 limit #{limit}
